// Build a set of comment_ids already in the database
const existingIds = new Set(
  $('Get Existing IDs').all()
    .map(i => i.json.comment_id)
    .filter(Boolean)
);

// Pull the prepared comments and keep only new, valid ones
const prepared = $('Prepare Fields').all();

const newComments = prepared.filter(item => {
  const id = item.json.comment_id;
  // drop null/empty ids (your scraper sometimes returns null comment_text/ids)
  if (!id) return false;
  return !existingIds.has(id);
});

return newComments;
